<template><section class="generic-table-panel"><header><strong>Tabla genérica</strong><span>{{ model.rows.length }} × {{ columnCount }}</span></header><div class="property-grid"><BioNexusFormField label="Ancho total" field-id="generic-width"><input id="generic-width" :value="tableWidth" class="bio-nexus-field" type="number" min="40" max="2400" @change="setWidth($event.target.value)"></BioNexusFormField><BioNexusFormField label="Alto total" field-id="generic-height"><input id="generic-height" :value="tableHeight" class="bio-nexus-field" type="number" min="18" max="1600" @change="setHeight($event.target.value)"></BioNexusFormField></div><div class="table-actions"><BioNexusActionButton size="sm" variant="secondary" icon="add" @click="addRow">Fila</BioNexusActionButton><BioNexusActionButton size="sm" variant="secondary" icon="add" @click="addColumn">Columna</BioNexusActionButton><BioNexusActionButton size="sm" variant="danger" icon="remove" :disabled="model.rows.length===1" @click="removeRow">Fila</BioNexusActionButton><BioNexusActionButton size="sm" variant="danger" icon="remove" :disabled="columnCount===1" @click="removeColumn">Columna</BioNexusActionButton></div><div class="cell-selector"><button v-for="(cell,index) in flatCells" :key="index" type="button" :class="{active:selectedIndexes.includes(index)}" @click="selectCell(index,$event)">{{ cellName(index) }}</button></div><div class="table-actions"><BioNexusActionButton size="sm" variant="secondary" icon="call_merge" :disabled="selectedIndexes.length<2" @click="mergeCells">Combinar</BioNexusActionButton><BioNexusActionButton size="sm" variant="secondary" icon="call_split" :disabled="!canUnmerge" @click="unmergeCell">Separar</BioNexusActionButton></div><template v-if="selectedCell"><BioNexusFormField label="Contenido" :field-id="id('content')" :help="selectedCell.content.length + ' de máximo 500 caracteres'" wide><textarea :id="id('content')" v-model="selectedCell.content" class="bio-nexus-field" maxlength="500" @input="changed"></textarea></BioNexusFormField><div class="token-list"><button v-for="token in tokens" :key="token.key" type="button" @click="insertToken(token.key)">{{ token.label }}</button></div><div class="property-grid"><BioNexusFormField label="Fuente" :field-id="id('font')"><BioNexusSearchableSelect :id="id('font')" v-model="selectedCell.fontFamily" :options="fontOptions" @change="changed" /></BioNexusFormField><BioNexusFormField label="Tamaño" :field-id="id('size')"><input :id="id('size')" v-model.number="selectedCell.fontSize" class="bio-nexus-field" type="number" min="8" max="72" @change="changed"></BioNexusFormField><BioNexusFormField label="Texto" :field-id="id('text-color')"><input :id="id('text-color')" v-model="selectedCell.textColor" class="bio-nexus-field color" type="color" @input="changed"></BioNexusFormField><BioNexusFormField label="Fondo" :field-id="id('background')"><input :id="id('background')" v-model="selectedCell.backgroundColor" class="bio-nexus-field color" type="color" @input="changed"></BioNexusFormField><BioNexusFormField label="Alineación" :field-id="id('align')"><BioNexusSearchableSelect :id="id('align')" v-model="selectedCell.align" :options="genericTableAlignments" @change="changed" /></BioNexusFormField><BioNexusFormField label="Alineación vertical" :field-id="id('vertical')"><BioNexusSearchableSelect :id="id('vertical')" v-model="selectedCell.verticalAlign" :options="genericTableVerticalAlignments" @change="changed" /></BioNexusFormField><BioNexusFormField label="Padding" :field-id="id('padding')"><input :id="id('padding')" v-model.number="selectedCell.padding" class="bio-nexus-field" type="number" min="0" max="40" @change="changed"></BioNexusFormField><BioNexusFormField label="Color de borde" :field-id="id('border-color')"><input :id="id('border-color')" v-model="selectedCell.borderColor" class="bio-nexus-field color" type="color" @input="changed"></BioNexusFormField><BioNexusFormField label="Grosor" :field-id="id('border-width')"><input :id="id('border-width')" v-model.number="selectedCell.borderWidth" class="bio-nexus-field" type="number" min="0" max="20" @change="changed"></BioNexusFormField><BioNexusFormField label="Estilo" :field-id="id('border-style')"><BioNexusSearchableSelect :id="id('border-style')" v-model="selectedCell.borderStyle" :options="genericTableLineStyles" @change="changed" /></BioNexusFormField></div><div class="format-actions"><button type="button" :class="{active:selectedCell.bold}" @click="toggle('bold')"><b>N</b></button><button type="button" :class="{active:selectedCell.italic}" @click="toggle('italic')"><i>C</i></button><button type="button" :class="{active:selectedCell.underline}" @click="toggle('underline')"><u>S</u></button></div></template></section></template>
<script setup>import{computed,ref,watch}from"vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusSearchableSelect from"@/components/ui/BioNexusSearchableSelect.vue";import{defaultGenericTableCell,genericTableAlignments,genericTableFonts,genericTableLineStyles,genericTableVerticalAlignments,genericTableSize,mergeGenericTableCells,resizeGenericTable,unmergeGenericTableCell}from"@/components/documents/designer/genericTableModel.js";const props=defineProps({model:{type:Object,required:true},tokens:{type:Array,default:()=>[]}}),emit=defineEmits(["change"]),selectedIndex=ref(0),selectedIndexes=ref([0]),selectionAnchor=ref(0),columnCount=computed(()=>props.model.rows[0]?.cells?.length||1),flatCells=computed(()=>props.model.rows.flatMap(row=>row.cells)),selectedCell=computed(()=>flatCells.value[selectedIndex.value]||null),fontOptions=genericTableFonts.map(value=>({value,label:value})),tableSize=computed(()=>genericTableSize(props.model)),tableWidth=computed(()=>tableSize.value.width),tableHeight=computed(()=>tableSize.value.height),canUnmerge=computed(()=>selectedCell.value&&!selectedCell.value.hidden&&(selectedCell.value.rowSpan>1||selectedCell.value.colSpan>1));watch(flatCells,value=>{if(selectedIndex.value>=value.length)selectedIndex.value=Math.max(0,value.length-1)});function id(suffix){return"generic-table-"+suffix}function changed(){emit("change")}function assignTable(value){Object.assign(props.model,value);changed()}function setWidth(value){assignTable(resizeGenericTable(props.model,Number(value),tableHeight.value))}function setHeight(value){assignTable(resizeGenericTable(props.model,tableWidth.value,Number(value)))}function selectCell(index,event){if(event?.shiftKey){const start=Math.min(selectionAnchor.value,index),end=Math.max(selectionAnchor.value,index);selectedIndexes.value=Array.from({length:end-start+1},(_,offset)=>start+offset)}else if(event?.ctrlKey||event?.metaKey){selectedIndexes.value=selectedIndexes.value.includes(index)?selectedIndexes.value.filter(value=>value!==index):[...selectedIndexes.value,index];selectionAnchor.value=index}else{selectedIndexes.value=[index];selectionAnchor.value=index}selectedIndex.value=index}function mergeCells(){try{assignTable(mergeGenericTableCells(props.model,selectedIndexes.value));selectedIndexes.value=[Math.min(...selectedIndexes.value)];selectedIndex.value=selectedIndexes.value[0]}catch(error){globalThis.alert(error.message)}}function unmergeCell(){assignTable(unmergeGenericTableCell(props.model,selectedIndex.value))}function cellName(index){return String.fromCharCode(65+(index%columnCount.value))+String(Math.floor(index/columnCount.value)+1)}function addRow(){props.model.rows.push({height:28,cells:Array.from({length:columnCount.value},()=>defaultGenericTableCell())});changed()}function removeRow(){if(props.model.rows.length===1)return;props.model.rows.pop();changed()}function addColumn(){props.model.columnWidths.push(160);for(const row of props.model.rows)row.cells.push(defaultGenericTableCell());changed()}function removeColumn(){if(columnCount.value===1)return;props.model.columnWidths.pop();for(const row of props.model.rows)row.cells.pop();changed()}function toggle(key){selectedCell.value[key]=!selectedCell.value[key];changed()}function insertToken(key){selectedCell.value.content+=(selectedCell.value.content?" ":"")+"{{"+key+"}}";changed()}</script>
<style scoped>.generic-table-panel{display:grid;gap:8px}.generic-table-panel>header{display:flex;justify-content:space-between}.table-actions{display:grid;grid-template-columns:1fr 1fr;gap:5px}.cell-selector{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;max-height:120px;overflow:auto}.cell-selector button,.format-actions button{min-height:30px;border:1px solid var(--bio-nexus-color-border);border-radius:5px;background:#fff}.cell-selector button.active,.format-actions button.active{border-color:var(--bio-nexus-color-primary);background:var(--bio-nexus-color-info-soft)}.token-list{display:flex;flex-wrap:wrap;gap:4px}.token-list button{padding:3px 6px;border:1px solid var(--bio-nexus-color-border);border-radius:999px;background:var(--bio-nexus-color-accent-soft);color:var(--bio-nexus-color-accent-strong)}.property-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.color{padding:3px}.format-actions{display:flex;gap:5px}.format-actions button{width:34px}</style>
